/**
 * Login of the admin panel (SPEC 13) and, since v0.8, of the bots control centre (SPEC 10.12):
 * the same OPAQUE flow, but completely independent of each other – own password record, own
 * sessions table, own cookie, own idle expiry, own login guard and rate limit. The initial
 * password is generated by the setup command and must be changed before anything else.
 */
import * as opaque from '@serenity-kit/opaque';
import type { FastifyInstance, FastifyRequest } from 'fastify';
import { TIME, TWO_FACTOR } from '@posteulen/shared/constants.ts';
import {
  AdminLoginStart,
  AdminPasswordFinish,
  AdminPasswordStart,
  AdminReauthStart,
  LoginFinish,
  LoginTwoFactor,
  ReauthFinish,
  TwoFactorDisable,
  TwoFactorEnable,
  TwoFactorSetup,
  type LoginStartResponse,
} from '@posteulen/shared/schemas/auth.ts';
import {
  checkSecondFactor,
  disableTwoFactor,
  finishSetup,
  startSetup,
  twoFactorActive,
  twoFactorStatus,
} from '../auth/two-factor.ts';
import type { Context } from '../context.ts';
import { HttpError, parse, emptyBody } from '../http/errors.ts';
import { randomId, randomToken, sha256 } from '../security/ids.ts';
import { clientKey } from '../security/ip.ts';
import { loginThrottle } from '../auth/user-routes.ts';
import { checkRegistrationRecord, opaqueStep } from '../auth/opaque-guard.ts';
import {
  clearSessionCookie,
  cookieSpec,
  setSessionCookie,
  specFor,
  type CookieSpec,
} from '../auth/sessions.ts';

export interface Panel {
  readonly key: 'admin' | 'bots';
  readonly origin: string;
  /** v1.4: the onion site of the panel, if set up (SPEC 16.5). */
  readonly torOrigin?: string | undefined;
  readonly cookie: 'pe_admin' | 'pe_bots';
  readonly table: 'admin' | 'bots_admin';
  readonly sessions: 'admin_sessions' | 'bots_admin_sessions';
  readonly idleMs: number;
  readonly attemptKind: 'admin' | 'bots';
  readonly reauthKind: 'admin-reauth' | 'bots-reauth';
}

/** Endpoints allowed while the initial password must still be changed (SPEC 13). */
const ALLOWED_BEFORE_CHANGE = new Set([
  '/api/me',
  '/api/logout',
  '/api/reauth/start',
  '/api/reauth/finish',
  '/api/password/start',
  '/api/password/finish',
]);

declare module 'fastify' {
  interface FastifyRequest {
    panelSession?: { tokenHash: Buffer; mustChangePassword: boolean };
  }
}

export type Authenticated = (request: FastifyRequest) => Promise<void>;

/** Registers login, logout, session, me, re-authentication and password change of a panel. */
export function registerPanelAuth(app: FastifyInstance, ctx: Context, panel: Panel): Authenticated {
  // v1.4: over Tor the cookie without Secure and __Host- (plain http onion site, SPEC 16.5).
  const base = cookieSpec(panel.origin, panel.cookie);
  const spec: CookieSpec =
    panel.torOrigin === undefined
      ? base
      : { ...base, tor: cookieSpec(panel.torOrigin, panel.cookie) };
  const cookieOf = (request: FastifyRequest): string | undefined =>
    request.cookies[specFor(spec, request).name];
  // v1.4: failed logins over Tor slow down only logins over Tor – a stranger in the Tor network
  // can never lock the admin out on the web (all Tor visitors share one address key).
  const guardKey = (request: FastifyRequest): string =>
    request.viaTor ? `${panel.key}:tor` : panel.key;
  const guard = ctx.guards[panel.key];
  const limiter = ctx.limits[panel.key];

  // Strict limit for everything on the panel's host (SPEC 13, 10.12).
  app.addHook('onRequest', async (request) => {
    const wait = limiter.hit(clientKey(request), ctx.now());
    if (wait > 0)
      throw new HttpError(429, 'rate_limited', { retryAfterSeconds: Math.ceil(wait / 1000) });
  });

  const sessionOf = (request: FastifyRequest) => {
    if (!request.panelSession) throw new HttpError(401, 'unauthorized');
    return request.panelSession;
  };

  const authenticated = async (request: FastifyRequest): Promise<void> => {
    const token = cookieOf(request);
    if (!token) throw new HttpError(401, 'unauthorized');
    const now = ctx.now();
    const hash = sha256(token);
    const row = ctx.db.get<{ last_used_at: number }>(
      `SELECT last_used_at FROM ${panel.sessions} WHERE token_hash = ?`,
      hash,
    );
    if (!row) throw new HttpError(401, 'unauthorized');
    if (now - row.last_used_at > panel.idleMs) {
      ctx.db.run(`DELETE FROM ${panel.sessions} WHERE token_hash = ?`, hash);
      throw new HttpError(401, 'unauthorized', { reason: 'session_expired' });
    }
    ctx.db.run(`UPDATE ${panel.sessions} SET last_used_at = ? WHERE token_hash = ?`, now, hash);
    const admin = ctx.db.get<{ must_change_password: number }>(
      `SELECT must_change_password FROM ${panel.table} WHERE id = 1`,
    );
    const mustChangePassword = admin?.must_change_password === 1;
    if (mustChangePassword && !ALLOWED_BEFORE_CHANGE.has(request.routeOptions.url ?? '')) {
      throw new HttpError(403, 'password_change_required');
    }
    request.panelSession = { tokenHash: hash, mustChangePassword };
  };

  function panelRecord(): { credential_id: string; opaque_record: string } {
    const row = ctx.db.get<{ credential_id: string; opaque_record: string }>(
      `SELECT credential_id, opaque_record FROM ${panel.table} WHERE id = 1`,
    );
    if (!row) throw new HttpError(503, 'admin_not_set_up');
    return row;
  }

  app.get('/api/altcha/challenge', async () => ctx.altcha.create(ctx.now()));

  app.post('/api/login/start', async (request): Promise<LoginStartResponse> => {
    const ip = clientKey(request);
    const body = parse(AdminLoginStart, request.body);
    const name = guardKey(request);
    const throttle = await loginThrottle(ctx, { name, ip, panel: panel.key }, body.altcha);
    if (throttle) return throttle as LoginStartResponse;
    const now = ctx.now();
    const admin = panelRecord();
    guard.fail(name, now);
    ctx.guards.ips.fail(ip, now);
    const { serverLoginState, loginResponse } = opaqueStep(() =>
      opaque.server.startLogin({
        serverSetup: ctx.secrets.opaqueServerSetup,
        userIdentifier: admin.credential_id,
        registrationRecord: admin.opaque_record,
        startLoginRequest: body.startLoginRequest,
      }),
    );
    const attemptId = randomId();
    ctx.attempts.set(
      attemptId,
      {
        kind: panel.attemptKind,
        userId: null,
        nameKey: name,
        ipKey: ip,
        serverLoginState,
        record: admin.opaque_record,
      },
      TIME.MINUTE,
      now,
    );
    return { status: 'ok', attemptId, loginResponse };
  });

  app.post('/api/login/finish', async (request, reply) => {
    const body = parse(LoginFinish, request.body);
    const now = ctx.now();
    const attempt = ctx.attempts.take(body.attemptId, now);
    if (!attempt || attempt.kind !== panel.attemptKind) throw new HttpError(401, 'login_failed');
    try {
      opaque.server.finishLogin({
        serverLoginState: attempt.serverLoginState,
        finishLoginRequest: body.finishLoginRequest,
      });
    } catch {
      throw new HttpError(401, 'login_failed');
    }
    // v1.0: a login that started before a password change must not finish after it.
    if (panelRecord().opaque_record !== attempt.record) throw new HttpError(401, 'login_failed');
    // v1.4.3: with a second factor the password alone opens nothing yet (SPEC 5.11).
    if (twoFactorActive(ctx.db, panel.key)) {
      const ticket = randomId();
      ctx.twoFactorTickets.set(
        ticket,
        {
          subject: panel.key,
          userId: null,
          nameKey: attempt.nameKey,
          ipKey: attempt.ipKey,
          record: attempt.record ?? '',
          tries: 0,
        },
        TWO_FACTOR.TICKET_MINUTES * TIME.MINUTE,
        now,
      );
      return { twoFactor: true, ticket };
    }
    return openSession(attempt.nameKey, attempt.ipKey, reply);
  });

  app.post('/api/login/two-factor', async (request, reply) => {
    const body = parse(LoginTwoFactor, request.body);
    const now = ctx.now();
    const ticket = ctx.twoFactorTickets.get(body.ticket, now);
    if (!ticket || ticket.subject !== panel.key) throw new HttpError(401, 'login_failed');
    if (panelRecord().opaque_record !== ticket.record) throw new HttpError(401, 'login_failed');
    if (!(await checkSecondFactor(ctx, panel.key, body.code, now))) {
      ticket.tries += 1;
      guard.fail(ticket.nameKey, now);
      if (ticket.tries >= TWO_FACTOR.TICKET_TRIES) {
        ctx.twoFactorTickets.delete(body.ticket);
        throw new HttpError(401, 'login_failed');
      }
      throw new HttpError(401, 'two_factor_wrong');
    }
    ctx.twoFactorTickets.delete(body.ticket);
    return openSession(ticket.nameKey, ticket.ipKey, reply);
  });

  function openSession(nameKey: string, ipKey: string, reply: import('fastify').FastifyReply) {
    const now = ctx.now();
    guard.reset(nameKey);
    ctx.guards.ips.succeed(ipKey);
    const token = randomToken();
    ctx.db.transaction(() => {
      ctx.db.run(`DELETE FROM ${panel.sessions} WHERE last_used_at < ?`, now - panel.idleMs);
      ctx.db.run(
        `INSERT INTO ${panel.sessions} (token_hash, created_at, last_used_at) VALUES (?, ?, ?)`,
        sha256(token),
        now,
        now,
      );
    });
    setSessionCookie(reply, spec, token);
    const admin = ctx.db.get<{ must_change_password: number }>(
      `SELECT must_change_password FROM ${panel.table} WHERE id = 1`,
    );
    return { mustChangePassword: admin?.must_change_password === 1 };
  }

  app.post('/api/logout', { preHandler: [authenticated, emptyBody] }, async (request, reply) => {
    ctx.db.run(`DELETE FROM ${panel.sessions} WHERE token_hash = ?`, sessionOf(request).tokenHash);
    clearSessionCookie(reply, spec);
    return { ok: true };
  });

  // Start of the admin app: answers without 401 when nobody is logged in.
  app.get('/api/session', async (request) => {
    const token = cookieOf(request);
    if (!token) return { state: 'none' };
    const row = ctx.db.get<{ last_used_at: number }>(
      `SELECT last_used_at FROM ${panel.sessions} WHERE token_hash = ?`,
      sha256(token),
    );
    if (!row || ctx.now() - row.last_used_at > panel.idleMs) {
      return { state: 'none' };
    }
    const admin = ctx.db.get<{ must_change_password: number }>(
      `SELECT must_change_password FROM ${panel.table} WHERE id = 1`,
    );
    return { state: 'active', mustChangePassword: admin?.must_change_password === 1 };
  });

  app.get('/api/me', { preHandler: authenticated }, async (request) => ({
    mustChangePassword: sessionOf(request).mustChangePassword,
    // v1.4.3: second factor switched on, backup codes left (SPEC 5.11).
    twoFactor: twoFactorStatus(ctx.db, panel.key),
  }));

  // ── Passwort ändern (Pflicht beim ersten Login, SPEC 13 item 8) ──
  app.post('/api/reauth/start', { preHandler: authenticated }, async (request) => {
    const body = parse(AdminReauthStart, request.body);
    const now = ctx.now();
    const ip = clientKey(request);
    const name = guardKey(request);
    const wait = guard.waitMs(name, now);
    if (wait > 0) return { status: 'wait', retryAfterSeconds: Math.ceil(wait / 1000) };
    const admin = panelRecord();
    guard.fail(name, now);
    const { serverLoginState, loginResponse } = opaqueStep(() =>
      opaque.server.startLogin({
        serverSetup: ctx.secrets.opaqueServerSetup,
        userIdentifier: admin.credential_id,
        registrationRecord: admin.opaque_record,
        startLoginRequest: body.startLoginRequest,
      }),
    );
    const attemptId = randomId();
    ctx.attempts.set(
      attemptId,
      {
        kind: panel.reauthKind,
        userId: null,
        nameKey: name,
        ipKey: ip,
        serverLoginState,
        purpose: body.purpose ?? 'password',
        record: admin.opaque_record,
      },
      TIME.MINUTE,
      now,
    );
    return { status: 'ok', attemptId, loginResponse };
  });

  app.post('/api/reauth/finish', { preHandler: authenticated }, async (request) => {
    const body = parse(ReauthFinish, request.body);
    const now = ctx.now();
    const attempt = ctx.attempts.take(body.attemptId, now);
    if (!attempt || attempt.kind !== panel.reauthKind) throw new HttpError(401, 'login_failed');
    try {
      opaque.server.finishLogin({
        serverLoginState: attempt.serverLoginState,
        finishLoginRequest: body.finishLoginRequest,
      });
    } catch {
      throw new HttpError(401, 'login_failed');
    }
    // v1.0: a login that started before a password change must not finish after it.
    if (panelRecord().opaque_record !== attempt.record) throw new HttpError(401, 'login_failed');
    // v1.4.3: also the second factor, if it is on (SPEC 5.11).
    if (
      twoFactorActive(ctx.db, panel.key) &&
      (body.code === undefined || !(await checkSecondFactor(ctx, panel.key, body.code, now)))
    ) {
      guard.fail(attempt.nameKey, now);
      throw new HttpError(401, 'two_factor_wrong');
    }
    guard.reset(attempt.nameKey);
    const token = randomId();
    ctx.reauthTokens.set(
      token,
      { subject: panel.key, purpose: `${panel.key}-${attempt.purpose ?? 'password'}` },
      5 * TIME.MINUTE,
      now,
    );
    return { token };
  });

  app.post('/api/password/start', { preHandler: authenticated }, async (request) => {
    const body = parse(AdminPasswordStart, request.body);
    const token = ctx.reauthTokens.get(body.token, ctx.now());
    if (token?.subject !== panel.key || token.purpose !== `${panel.key}-password`)
      throw new HttpError(403, 'reauth_required');
    const { registrationResponse } = opaqueStep(() =>
      opaque.server.createRegistrationResponse({
        serverSetup: ctx.secrets.opaqueServerSetup,
        userIdentifier: panelRecord().credential_id,
        registrationRequest: body.registrationRequest,
      }),
    );
    return { registrationResponse };
  });

  app.post('/api/password/finish', { preHandler: authenticated }, async (request, reply) => {
    const body = parse(AdminPasswordFinish, request.body);
    const now = ctx.now();
    const token = ctx.reauthTokens.get(body.token, now);
    if (token?.subject !== panel.key || token.purpose !== `${panel.key}-password`)
      throw new HttpError(403, 'reauth_required');
    // v0.6.1: a record the server cannot use would lock the admin out.
    checkRegistrationRecord(
      ctx.secrets.opaqueServerSetup,
      panelRecord().credential_id,
      body.registrationRecord,
    );
    ctx.reauthTokens.delete(body.token);
    const session = randomToken();
    ctx.db.transaction(() => {
      ctx.db.run(
        `UPDATE ${panel.table} SET opaque_record = ?, must_change_password = 0 WHERE id = 1`,
        body.registrationRecord,
      );
      ctx.db.run(`DELETE FROM ${panel.sessions}`);
      ctx.db.run(
        `INSERT INTO ${panel.sessions} (token_hash, created_at, last_used_at) VALUES (?, ?, ?)`,
        sha256(session),
        now,
        now,
      );
    });
    setSessionCookie(reply, spec, session);
    return { ok: true };
  });

  // ── Zweiter Faktor (SPEC 5.11) – ein- und ausschalten nur nach erneuter Anmeldung ──
  const twoFactorToken = (token: string): void => {
    const found = ctx.reauthTokens.get(token, ctx.now());
    if (found?.subject !== panel.key || found.purpose !== `${panel.key}-two_factor`)
      throw new HttpError(403, 'reauth_required');
    ctx.reauthTokens.delete(token);
  };

  app.post('/api/two-factor/setup', { preHandler: authenticated }, async (request) => {
    const body = parse(TwoFactorSetup, request.body);
    twoFactorToken(body.token);
    const account = panel.key === 'admin' ? 'Adminpanel' : 'Bots-Kontrollzentrum';
    return startSetup(ctx, panel.key, `${account} ${new URL(panel.origin).hostname}`, ctx.now());
  });

  app.post('/api/two-factor/enable', { preHandler: authenticated }, async (request) => {
    const body = parse(TwoFactorEnable, request.body);
    const codes = await finishSetup(ctx, panel.key, null, body.code, ctx.now());
    return { backupCodes: codes, twoFactor: twoFactorStatus(ctx.db, panel.key) };
  });

  app.post('/api/two-factor/disable', { preHandler: authenticated }, async (request) => {
    const body = parse(TwoFactorDisable, request.body);
    twoFactorToken(body.token);
    disableTwoFactor(ctx.db, panel.key);
    return { twoFactor: twoFactorStatus(ctx.db, panel.key) };
  });

  return authenticated;
}
